#!/bin/bash
# contra_build.sh - AUTO-GENERATED by compose_contra.py. Edit game/contra/*.cs, re-run composer; never hand-edit.
set -e
UNITY=/content/ue/Editor/Unity
DEMO=/content/work/demo
PROJ=/content/work/runandgun
BUNDLE=$PROJ/Builds/WebGL/probe

echo "=== PREFLIGHT ==="
test -f /content/unity_bin.txt || { echo NO_UNITY_BIN; exit 6; }
test -x "$UNITY" || { echo NO_EDITOR_BIN; exit 6; }
echo PREFLIGHT_OK

echo "=== BUSY CHECK (wait for idle editor) ==="
BWAIT=0
while pgrep -f "Editor/Unity" >/dev/null 2>&1; do
  BWAIT=$((BWAIT+1))
  if [ "$BWAIT" -gt 90 ]; then echo UNITY_BUSY_TIMEOUT; exit 7; fi
  echo "UNITY_BUSY_WAITING $BWAIT"
  sleep 20
done
echo UNITY_IDLE
echo NOT_BUSY

echo "=== PROJECT ==="
if [ ! -d "$PROJ/Assets" ]; then
  if [ -d "$DEMO/Assets" ]; then
    echo CLONE_FROM_DEMO
    rm -rf "$PROJ"
    cp -a "$DEMO" "$PROJ"
  else
    echo CREATE_PROJECT_FRESH
    rm -rf "$PROJ"
    "$UNITY" -batchmode -quit -nographics -createProject "$PROJ" -logFile /content/create_rag.log
    echo CREATE_DONE
  fi
fi
rm -rf "$PROJ/Assets/Demo" "$PROJ/Assets/Scenes" "$PROJ/Builds" "$PROJ/Temp"
test -d "$PROJ/Assets" || { echo NO_PROJECT; exit 6; }
mkdir -p "$PROJ/Assets/Editor" "$PROJ/Assets/Contra"

echo "=== ENSURE UGUI (bare -createProject lacks UnityEngine.UI) ==="
python3 - "$PROJ" <<'PYEOF'
import json, sys, os
p = os.path.join(sys.argv[1], 'Packages', 'manifest.json')
m = json.load(open(p))
m.setdefault('dependencies', {})
if 'com.unity.ugui' not in m['dependencies']:
    m['dependencies']['com.unity.ugui'] = '2.0.0'
    open(p, 'w').write(json.dumps(m, indent=2))
    print('UGUI_ADDED')
else:
    print('UGUI_PRESENT')
PYEOF
echo PROJECT_READY

cat > "$PROJ/Assets/Editor/BuildScript.cs" <<'CSEOF'
using System.IO; using System.Linq; using UnityEngine; using UnityEditor; using UnityEditor.SceneManagement;
public static class BuildScript {
    [MenuItem("Build/Perform")]
    public static void PerformBuild() {
        var scenes = new string[] { "Assets/Scenes/Sample.unity" };
        if (!File.Exists(scenes[0])) {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            System.IO.Directory.CreateDirectory("Assets/Scenes");
            EditorSceneManager.SaveScene(scene, scenes[0]);
            Debug.Log("SCENE_CREATED_BY_SCRIPT");
        }
        EditorBuildSettings.scenes = scenes.Select(s => new EditorBuildSettingsScene(s, true)).ToArray();
        AssetDatabase.Refresh(ImportAssetOptions.ForceUpdate);
        AssetDatabase.SaveAssets();
        if (!File.Exists(scenes[0])) throw new System.Exception("SCENE_SAVE_FAILED: " + scenes[0]);
        var target = BuildTarget.WebGL; var outDir = "Builds/WebGL/probe";
        if (target == BuildTarget.WebGL) PlayerSettings.WebGL.compressionFormat = WebGLCompressionFormat.Disabled;
        var report = BuildPipeline.BuildPlayer(scenes, outDir, target, BuildOptions.None);
        if (report.summary.result != UnityEditor.Build.Reporting.BuildResult.Succeeded) throw new System.Exception("BUILD_FAILED: " + report.summary.result);
        Debug.Log("BUILD_OK " + report.summary.totalSize + " bytes");
    }
}
